  assert.equal(isValidDate('15-01-2024'), false);
});

test('isValidDate rejects invalid dates', () => {
  assert.equal(isValidDate('2024-13-01'), false);
  assert.equal(isValidDate('2024-00-01'), false);
  assert.equal(isValidDate('2024-02-30'), false); // invalid day
  assert.equal(isValidDate('2023-02-29'), false); // not a leap year
  assert.equal(isValidDate('2024-01-32'), false);
});

test('isValidDate rejects non-string input', () => {
  assert.equal(isValidDate(null), false);
  assert.equal(isValidDate(undefined), false);
  assert.equal(isValidDate(123), false);
  assert.equal(isValidDate({ year: 2024, month: 1, day: 15 }), false);
});

test('isValidDate accepts leap year dates', () => {
  assert.equal(isValidDate('2024-02-29'), true);
  assert.equal(isValidDate('2000-02-29'), true);
  assert.equal(isValidDate('2100-02-29'), false); // not a leap year
});

test('addDays adds days to a date', () => {
  assert.equal(addDays('2024-01-15', 1), '2024-01-16');
  assert.equal(addDays('2024-01-15', 10), '2024-01-25');
  assert.equal(addDays('2024-01-15', 366), '2025-01-15'); // 2024 is a leap year (366 days)
});

test('addDays handles month boundaries', () => {
  assert.equal(addDays('2024-01-31', 1), '2024-02-01');
  assert.equal(addDays('2024-02-29', 1), '2024-03-01'); // leap year
  assert.equal(addDays('2024-12-31', 1), '2025-01-01');
});

test('addDays can subtract days (negative n)', () => {
  assert.equal(addDays('2024-01-15', -1), '2024-01-14');
  assert.equal(addDays('2024-01-15', -10), '2024-01-05');
  assert.equal(addDays('2024-01-01', -1), '2023-12-31');
});

test('addDays handles year boundaries', () => {
  assert.equal(addDays('2023-12-31', 1), '2024-01-01');
  assert.equal(addDays('2024-01-01', -1), '2023-12-31');
});

test('addDays with zero returns same date', () => {
  assert.equal(addDays('2024-01-15', 0), '2024-01-15');
});

test('daysBetween calculates days between dates', () => {
  assert.equal(daysBetween('2024-01-15', '2024-01-16'), 1);
  assert.equal(daysBetween('2024-01-15', '2024-01-25'), 10);
  assert.equal(daysBetween('2024-01-15', '2025-01-15'), 366); // 2024 is a leap year (366 days)
});

test('daysBetween handles same date', () => {
  assert.equal(daysBetween('2024-01-15', '2024-01-15'), 0);
});

test('daysBetween returns negative for reverse dates', () => {
  assert.equal(daysBetween('2024-01-16', '2024-01-15'), -1);
  assert.equal(daysBetween('2024-01-25', '2024-01-15'), -10);
  assert.equal(daysBetween('2025-01-15', '2024-01-15'), -365);
});

test('daysBetween handles month boundaries', () => {
  assert.equal(daysBetween('2024-01-31', '2024-02-01'), 1);
  assert.equal(daysBetween('2024-02-29', '2024-03-01'), 1);
  assert.equal(daysBetween('2024-12-31', '2025-01-01'), 1);
});

test('daysBetween calculates across year boundary', () => {
  assert.equal(daysBetween('2023-12-31', '2024-01-01'), 1);
  assert.equal(daysBetween('2023-12-01', '2024-01-01'), 31);
});

test('daysBetween is consistent with addDays', () => {
  const start = '2024-01-15';
  const end = addDays(start, 10);
  assert.equal(daysBetween(start, end), 10);
});

test('daysBetween with leap year', () => {
  // 2024 is a leap year, Feb has 29 days
  assert.equal(daysBetween('2024-02-28', '2024-02-29'), 1);
  assert.equal(daysBetween('2024-02-29', '2024-03-01'), 1);
  assert.equal(daysBetween('2024-02-28', '2024-03-01'), 2);
});

