node -e "
import { isValidDate, addDays, daysBetween } from './src/dates.js';

console.log('=== Date Utilities (UTC-based) ===\n');

// isValidDate examples
console.log('isValidDate() tests:');
console.log('  isValidDate(\"2024-01-15\") =', isValidDate('2024-01-15'));
console.log('  isValidDate(\"2024-02-29\") =', isValidDate('2024-02-29')); // leap year
console.log('  isValidDate(\"2023-02-29\") =', isValidDate('2023-02-29')); // not leap year
console.log('  isValidDate(\"2024-13-01\") =', isValidDate('2024-13-01'));
console.log('  isValidDate(\"01/15/2024\") =', isValidDate('01/15/2024'));

// addDays examples
console.log('\naddDays() tests:');
console.log('  addDays(\"2024-01-15\", 1) =', addDays('2024-01-15', 1));
console.log('  addDays(\"2024-01-31\", 1) =', addDays('2024-01-31', 1)); // month boundary
console.log('  addDays(\"2024-12-31\", 1) =', addDays('2024-12-31', 1)); // year boundary
console.log('  addDays(\"2024-01-15\", -5) =', addDays('2024-01-15', -5)); // subtract days

// daysBetween examples
console.log('\ndaysBetween() tests:');
console.log('  daysBetween(\"2024-01-15\", \"2024-01-25\") =', daysBetween('2024-01-15', '2024-01-25'));
console.log('  daysBetween(\"2024-01-15\", \"2024-01-15\") =', daysBetween('2024-01-15', '2024-01-15'));
console.log('  daysBetween(\"2024-01-25\", \"2024-01-15\") =', daysBetween('2024-01-25', '2024-01-15'));
console.log('  daysBetween(\"2024-01-15\", \"2025-01-15\") =', daysBetween('2024-01-15', '2025-01-15')); // leap year = 366 days

// Demonstrate consistency
console.log('\nConsistency check (addDays + daysBetween):');
const start = '2024-03-01';
const days = 50;
const end = addDays(start, days);
const calc = daysBetween(start, end);
console.log('  Start:', start);
console.log('  Add 50 days: ', end);
console.log('  daysBetween(start, end) =', calc);
console.log('  Match:', days === calc);
"

